#include <stdio.h>
#include <stdbool.h>

#include "esp_random.h"

// Weights generated by tinyML_ac.py
#include "ac_model_weights.h"

#define N_SAMPLES 50

#define TEMP_RANGE 45		// 0..45 C
#define LIGHT_RANGE 100		// 0..100 %
#define HUM_RANGE 100		// 0..100 %

// ANN: 3 inputs -> N_HIDDEN ReLU nodes -> 1 sigmoid output
bool predict(int temperature, int light, int humidity)
{
	float input[N_INPUT] = {
		temperature / TEMP_MAX,
		light / LIGHT_MAX,
		humidity / HUM_MAX
	};

	float result = b2;

	for (int j = 0; j < N_HIDDEN; j++)
	{
		float tmp = b1[j];

		for (int i = 0; i < N_INPUT; i++)
		{
			tmp += input[i] * w1[i][j];
		}

		tmp = tmp < 0 ? 0 : tmp; // relu

		result += tmp * w2[j];
	}

	// sigmoid(result) > 0.5 is the same as result > 0, so no exp() is needed
	return result > 0;
}

// The observation the model was trained on, used only to check the predictions
static bool ac_rule(int temperature, int light, int humidity)
{
	return light > 70 && (temperature > 25 || humidity > 65);
}

void app_main(void)
{
	int correct = 0;

	printf("\n  #  Temp  Light  Humidity    AC   (rule)\n");

	for (int i = 0; i < N_SAMPLES; i++)
	{
		int temperature = esp_random() % (TEMP_RANGE + 1);
		int light = esp_random() % (LIGHT_RANGE + 1);
		int humidity = esp_random() % (HUM_RANGE + 1);

		bool ac_on = predict(temperature, light, humidity);
		bool expected = ac_rule(temperature, light, humidity);

		correct += ac_on == expected;

		printf(" %2d  %3dC   %3d%%      %3d%%   %s   (%s)%s\n", i + 1, temperature, light, humidity,
			   ac_on ? "ON " : "OFF", expected ? "ON " : "OFF", ac_on == expected ? "" : "  <-- mismatch");
	}

	printf("\nPredictions matching the rule: %d/%d\n", correct, N_SAMPLES);
}
